    name = bp['path'].split('/')[-1]
    bpkgs = {p['id']: p['resolvedVersion'] for fw in bp['frameworks'] for p in fw['topLevelPackages']}
    apkgs = {p['id']: p['resolvedVersion'] for fw in ap['frameworks'] for p in fw['topLevelPackages']}
    for pkg in sorted(set(list(bpkgs.keys()) + list(apkgs.keys()))):
